package threadctx

import (
	_ "embed"
	"strings"
)

// The word lists the masker reads, generated by cmd/gen-mask-words from
// vendored sources; each file's header states its sources, their licenses and
// the command that regenerates it.
var (
	//go:embed common_words.txt
	commonWordsFile string
	//go:embed names.txt
	personNamesFile string

	// commonWords are the common English words, contractions included.
	commonWords = wordSet(commonWordsFile)
	// personNames are given and family names. A common word among them is
	// still masked when it stands capitalized where no sentence begins.
	personNames = wordSet(personNamesFile)
)

func wordSet(file string) map[string]bool {
	out := map[string]bool{}
	for line := range strings.Lines(file) {
		line = strings.TrimSpace(line)
		if line != "" && !strings.HasPrefix(line, "#") {
			out[line] = true
		}
	}
	return out
}

// ordinary reports a common word that is no person's name.
func ordinary(lower string) bool {
	return commonWords[lower] && !personNames[lower]
}
